const mails = await api.peek("/mails", { label: "환불" });
const gold = await api.peek("/customers", { tier: "gold" });
return { mails, gold };

const mails = await api.get("/mails", { label: "환불" });
const gold = await api.get("/customers", { tier: "gold" });
const items = mails.items || [];
console.log("mail sample keys:", items[0] ? Object.keys(items[0]) : []);
const goldIds = new Set((gold.items || []).map(c => String(c.id)));
const senderIds = new Set(items.map(m => String(m.customer_id)));
const matched = (gold.items || []).filter(c => senderIds.has(String(c.id))).map(c => c.name);
return { mailCount: items.length, matched };

const all = await api.get("/mails", {});
const items = all.items || [];
const labels = [...new Set(items.map(m => m.label))];
console.log("total:", items.length, "labels:", labels);
console.log("keys:", items[0] ? Object.keys(items[0]) : []);
return { total: items.length, labels };

const mails = await api.get("/mails", { label: "refund" });
const gold = await api.get("/customers", { tier: "gold" });
const items = mails.items || [];
const senderIds = new Set(items.map(m => String(m.customer_id)));
const matched = (gold.items || []).filter(c => senderIds.has(String(c.id))).map(c => ({ id: c.id, name: c.name }));
return { refundMailCount: items.length, matched };

